//! What each tool TAKES: one struct per tool, its `inputSchema` generated by `schemars`.
//!
//! The doc comment of a field is that argument's `description`, and a client reads it. Each `///`
//! line break is a space on the wire, so wrap at a space. A field with no doc comment has no
//! `description`; an `Option` is an optional argument, anything else a required one, in the order
//! declared here.
//!
//! ⚠ **The handlers still read `Value`** (`crates/vike-mcp/src/tool_verbs.rs`, each tool family), and
//! nothing here parses a call. Their refusals are pinned word for word by the goldens and are not what
//! a derived `Deserialize` would say, so a struct is the SCHEMA and no more. That is why no field is
//! ever read.
//!
//! ⚠ **`Deserialize` is on every struct, and it is not decoration: it is where the declared order
//! lives.** A JSON map sorts its keys (`serde_json/preserve_order` flips every map in the build, the
//! root `Cargo.toml` says so beside `schemars`), and `skills/` lists arguments in declared order.
//! `crates/vike-mcp/src/tool_schemas.rs`'s `declared_fields` reads the order out of the derive.
#![expect(
    dead_code,
    reason = "a struct here is a schema, its fields are never read: the module doc"
)]

use schemars::{JsonSchema, Schema, SchemaGenerator, json_schema};
use serde::Deserialize;
use serde_json::{Map, Value, json};

/// The `inputSchema` of `T` as a client sees it: `type`, `properties`, and `required` when something
/// is. What `schemars` adds beside those (`$schema`, `title`, `format`, `minimum`,
/// `additionalProperties`, a `null` in an optional's `type`) is no part of what this surface
/// advertises, so it is kept out by naming what stays.
pub(super) fn input_schema<T: JsonSchema>() -> Value {
    let raw = schemars::schema_for!(T).to_value();
    let properties: Map<String, Value> = raw["properties"]
        .as_object()
        .into_iter()
        .flatten()
        .map(|(name, property)| (name.clone(), advertised(property)))
        .collect();
    let mut schema = json!({ "type": "object", "properties": properties });
    if let Some(required) = raw.get("required") {
        schema["required"] = required.clone();
    }
    schema
}

/// One argument: its one `type`, its `enum`, its `description` on one line.
fn advertised(property: &Value) -> Value {
    let kind = match &property["type"] {
        Value::Array(types) => types.iter().find(|t| t.as_str() != Some("null")),
        kind => Some(kind),
    };
    let mut out = Map::new();
    if let Some(kind) = kind {
        out.insert("type".to_string(), kind.clone());
    }
    if let Some(values) = property.get("enum") {
        out.insert("enum".to_string(), values.clone());
    }
    if let Some(description) = property["description"].as_str() {
        out.insert("description".to_string(), json!(description.replace('\n', " ")));
    }
    Value::Object(out)
}

/// `run_sweep`'s `optimizer`: rendered from the protocol's own roster, never typed out. §15.1 of
/// `docs/superpowers/specs/2026-09-12-backtest-cli-surface-design.md` makes this the AGENT leg of the
/// one-roster gate: a model can only ask for a method the SCHEMA names, so a hand-typed list here would
/// leave every agent a grid user the day a fifth method shipped, which is exactly the state §12 says
/// this stage exists to end.
fn search_method_schema(_: &mut SchemaGenerator) -> Schema {
    let methods = vike_model::run_request::search_methods::SEARCH_METHODS;
    json_schema!({ "type": "string", "enum": methods })
}

/// The arguments every write tool takes, spliced into each one's schema (`tool_schemas.rs`'s `row`,
/// on `is_write_tool`), so their wording cannot drift between tools, which is how the old inline
/// copies ended up in four different spellings.
#[derive(Deserialize, JsonSchema)]
pub(super) struct WriteGate {
    /// optional rationale — WHY this command is being issued. Recorded in the node's audit trail
    /// (control characters stripped, capped at 512 chars); never reaches the order, the core, or the
    /// venue.
    reason: Option<String>,
    /// must be true AND accompanied by a valid `preview_token` to execute; either one missing returns
    /// a preview instead
    confirm: Option<bool>,
    /// the `preview_token` returned by this tool's preview call. Fires ONCE, expires after 60s, and is
    /// BOUND to the exact command it previewed — confirming a different command with it is refused.
    preview_token: Option<String>,
}

